import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

function BookingPage() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: "",
    vehicleNo: "",
    vehicleType: "",
    slotNumber: "",
    date: "",
    time: "",
    duration: "",
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleProceed = async () => {
    const { name, vehicleNo, vehicleType, slotNumber, date, time, duration } =
      formData;

    if (!name || !vehicleNo || !vehicleType || !slotNumber || !date || !time || !duration) {
      alert("Please fill all fields");
      return;
    }

    try {
      // ✅ send booking to backend DB
      await axios.post("http://localhost:8080/api/bookings", formData);

      alert("Booking Successful!");
      navigate("/payment", { state: formData });
    } catch (err) {
      console.error("Booking failed:", err);
      alert("Booking failed. Please try again.");
    }
  };

  return (
    <div>
      <h1>Book a Parking Slot</h1>
      <input
        type="text"
        name="name"
        placeholder="Your Name"
        value={formData.name}
        onChange={handleChange}
      />
      <input
        type="text"
        name="vehicleNo"
        placeholder="Vehicle Number"
        value={formData.vehicleNo}
        onChange={handleChange}
      />
      <input
        type="text"
        name="slotNumber"
        placeholder="Slot Number"
        value={formData.slotNumber}
        onChange={handleChange}
      />
      <input
        type="date"
        name="date"
        value={formData.date}
        onChange={handleChange}
      />
      <input
        type="time"
        name="time"
        value={formData.time}
        onChange={handleChange}
      />
      <input
        type="number"
        name="duration"
        placeholder="Duration (hours)"
        value={formData.duration}
        onChange={handleChange}
      />

      <button onClick={handleProceed}>Proceed to Payment</button>
    </div>
  );
}

export default BookingPage;
